challenge.verificationSource:
mod solution;

fn valid(_input: &str, actual: &str, expected: &str) -> bool { actual == expected }

fn main() {
    let cases = [
        ("matrix=[[0,3,10],[inf,0,2],[inf,inf,0]]","5"),
        ("matrix=[[0,7,2],[inf,0,1],[inf,inf,0]]","2"),
        ("matrix=[[0,1,5],[inf,0,1],[inf,inf,0]]","2"),
        ("matrix=[[0,9,3],[inf,0,1],[inf,inf,0]]","3"),
        ("matrix=[[0,2,8],[inf,0,3],[inf,inf,0]]","5"),
        ("  \nmatrix=[[0,3,10],[inf,0,2],[inf,inf,0]]\n  ","5"),
        ("\nmatrix=[[0,2,8],[inf,0,3],[inf,inf,0]]\n","5")
    ];
    for (i,(input,expected)) in cases.iter().enumerate() {
        let actual = solution::solve(input);
        if !valid(input,&actual,expected) { eprintln!("PRIVATE CASE {} FAILED",i+1); std::process::exit(1); }
    }
    println!("PASS floyd-warshall");
}
